{"python_code":"def _axial_cylinder(radius, start, end):
    return Part.makeCylinder(
        radius, end - start,
        App.Vector(start, 0, 0), App.Vector(1, 0, 0)
    )


def _finish(shape, frame, name):
    shape = shape.removeSplitter()
    solids = shape.Solids
    if len(solids) != 1 or not shape.isValid():
        raise ValueError(name + ' must be one valid solid')
    solid = solids[0].copy()
    solid.Placement = frame.multiply(solid.Placement)
    return solid


def build(p, frame):
    x0 = p['x0']
    shoulder = p['shoulder']
    sleeve_end = x0 + p['sleeve_length']

    bearing = _axial_cylinder(
        p['outer_radius'], shoulder, p['bearing_end']
    )
    for radius, start, end in (
        (p['rear_bore'], shoulder, p['relief_start']),
        (p['relief_radius'], p['relief_start'], p['relief_end']),
        (p['front_bore'], p['relief_end'], p['bearing_end']),
    ):
        bearing = bearing.cut(_axial_cylinder(radius, start, end))

    barrel = _axial_cylinder(p['sleeve_radius'], x0, sleeve_end)
    flange = _axial_cylinder(p['outer_radius'], x0, shoulder)
    sleeve = barrel.fuse(flange)

    void = _axial_cylinder(p['sleeve_bore'], x0, sleeve_end)
    count = int(p['groove_count'])
    if count < 0 or count != p['groove_count']:
        raise ValueError('groove_count must be a nonnegative integer')

    for i in range(count):
        groove = Part.makeBox(
            p['sleeve_length'], p['groove_root'], p['groove_width'],
            App.Vector(x0, 0, -p['groove_width'] / 2.0)
        )
        groove.rotate(
            App.Vector(0, 0, 0), App.Vector(1, 0, 0),
            360.0 * i / count
        )
        void = void.fuse(groove)

    sleeve = sleeve.cut(void.removeSplitter())
    return {
        'bearing': _finish(bearing, frame, 'bearing'),
        'sleeve': _finish(sleeve, frame, 'sleeve'),
    }
